const schemes={graphite:['#24272b','#1b1e22','#e0e2e5','#a8b0b8','#b8c8bc'],porcelain:['#eeeae3','#ddd8cf','#2d3437','#606b6e','#426860'],sage:['#29332f','#1d2824','#e0e8df','#a4b5ab','#c7c7a2'],ink:['#242b38','#19212d','#e0e4ed','#a7b2c4','#b3c6e8'],rose:['#362e33','#272126','#eee0e7','#bcaab4','#e0bbbe']};
export function applyAppearance(p){let colors=schemes[p.appearance]||schemes.graphite;if(p.appearance==='custom'&&/^#[0-9a-f]{6}$/i.test(p.baseColor)&&/^#[0-9a-f]{6}$/i.test(p.accentColor)){const a=p.baseColor.match(/\w\w/g).map(v=>parseInt(v,16)),light=a[0]*.2126+a[1]*.7152+a[2]*.0722>150,shift=n=>'#'+a.map(v=>Math.max(0,Math.min(255,v+n)).toString(16).padStart(2,'0')).join('');colors=[p.baseColor,shift(light?-14:-10),light?'#252a2c':'#eceff1',light?'#555f63':'#b1bbc1',p.accentColor];}for(const [i,key]of ['panel','stage','text','subtle','focus'].entries())document.documentElement.style.setProperty('--ui-'+key,colors[i]);document.documentElement.style.colorScheme=['porcelain'].includes(p.appearance)?'light':'dark';document.body.dataset.layout=['left','right'].includes(p.layout)?p.layout:'left';document.body.dataset.density=p.density==='compact'?'compact':'comfortable';}
